 31→import { Button } from "@/components/ui/button";
 32→
 33→export function Chat({
 34→  connected,
 35→  loading,
 36→  status,
 37→  agentLabel,
 38→  messages,
 39→  rawMessages,
 40→  activeModel,
 41→  selectedModel,
 42→  onModelChange,
 43→  onSendMessage,
 44→  onSpawnAgent,
 45→  onRespondToControl,
 46→  onRespondToUserQuestion,
