 96→  const [showSystemPrompt, setShowSystemPrompt] = useState(false);
 97→  const [showRaw, setShowRaw] = useState(false);
 98→  const [showContext, setShowContext] = useState(false);
 99→  const [showSlashMenu, setShowSlashMenu] = useState(false);
100→  const [slashQuery, setSlashQuery] = useState("");
101→  const [slashHighlight, setSlashHighlight] = useState(0);
102→  const [atBottom, setAtBottom] = useState(true);
103→  const virtuosoRef = useRef<VirtuosoHandle>(null);
104→  const inputRef = useRef<HTMLInputElement>(null);
105→
106→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
107→  const isActive = status === "connected" || status === "thinking";
108→  const isArchived = status === "done" || status === "disconnected" || status === "error";
109→
110→  function handleSubmit(e: React.FormEvent) {
111→    e.preventDefault();
112→    const trimmed = input.trim();
113→    if (!trimmed) return;
114→
115→    if (isActive) {
116→      onSendMessage(trimmed);
117→    } else {
118→      onSpawnAgent(trimmed, systemPrompt.trim() || undefined);
119→      setSystemPrompt("");
120→      setShowSystemPrompt(false);
121→    }
122→    setInput("");
123→    setShowSlashMenu(false);
124→  }
125→
126→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
127→    const value = e.target.value;
128→    setInput(value);
129→
130→    if (value.startsWith("/")) {
131→      setShowSlashMenu(true);
132→      setSlashQuery(value.slice(1));
133→      setSlashHighlight(0);
134→    } else {
135→      setShowSlashMenu(false);
136→      setSlashQuery("");
137→    }
138→  }
139→
140→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
141→    if (!showSlashMenu) return;
142→    const filtered = filterCommands(slashQuery);
143→    if (filtered.length === 0) return;
144→
145→    if (e.key === "ArrowDown") {
146→      e.preventDefault();
147→      setSlashHighlight((i) => (i + 1) % filtered.length);
148→    } else if (e.key === "ArrowUp") {
149→      e.preventDefault();
150→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
151→    } else if (e.key === "Enter") {
152→      e.preventDefault();
153→      handleCommandSelect(filtered[slashHighlight]);
154→    } else if (e.key === "Escape") {
155→      e.preventDefault();
156→      setShowSlashMenu(false);
157→    } else if (e.key === "Tab") {
158→      e.preventDefault();
159→      setInput(`/${filtered[slashHighlight].name} `);
160→      setShowSlashMenu(false);
161→    }
162→  }
163→
164→  function handleCommandSelect(command: SlashCommand) {
165→    setShowSlashMenu(false);
166→    setSlashQuery("");
167→    setInput("");
168→
169→    if (command.clientSide) {
170→      if (command.name === "clear") {
171→        onClearHistory?.();
172→      } else if (command.name === "context") {
173→        setShowContext((v) => !v);
174→      }
175→      return;
176→    }
177→
178→    const commandText = `/${command.name}`;
