220→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
221→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
222→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
223→            </div>
224→            <span className="text-xs text-muted-foreground">
225→              {connected ? "Loading messages..." : "Connecting..."}
226→            </span>
227→          </div>
228→        ) : showRaw ? (
229→          <div className="h-full overflow-y-auto p-2 md:p-4 space-y-1">
230→            {rawMessages.length === 0 ? (
231→              <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
232→                No raw messages yet
233→              </div>
234→            ) : (
235→              rawMessages.map((msg, i) => (
236→                <RawMessage key={i} message={msg} index={i} />
237→              ))
238→            )}
239→          </div>
240→        ) : (
241→          <Virtuoso
242→            ref={virtuosoRef}
243→            data={displayItems}
244→            style={{ height: "100%" }}
245→            initialTopMostItemIndex={displayItems.length - 1}
246→            followOutput={(isAtBottom) => isAtBottom ? "smooth" : false}
247→            atBottomStateChange={setAtBottom}
248→            increaseViewportBy={200}
249→            itemContent={(_index, item) => (
250→              <div className="px-2 pb-2 md:px-4">
251→                {item.kind === "condensed" ? (
252→                  <CondensedToolGroup key={item.id} group={item} onSendMessage={onSendMessage} />
253→                ) : item.message.userQuestion ? (
254→                  <UserQuestion key={item.message.id} message={item.message} onRespond={onRespondToUserQuestion} />
255→                ) : item.message.controlRequest ? (
256→                  <ControlRequest key={item.message.id} message={item.message} onRespond={onRespondToControl} />
257→                ) : (
258→                  <Message key={item.message.id} message={item.message} onSendMessage={onSendMessage} />
259→                )}
260→              </div>
261→            )}
262→            components={{
263→              Header: () => <div className="h-2" />,
264→              Footer: showContext ? () => (
265→                <div className="px-2 pb-2 md:px-4">
266→                  <div className="flex flex-col gap-0.5 items-start">
267→                    <ContextUsageCard rawMessages={rawMessages} activeModel={activeModel} />
268→                  </div>
269→                </div>
270→              ) : undefined,
271→              EmptyPlaceholder: () => (
272→                <div className="flex h-full flex-col items-center justify-center gap-4 text-muted-foreground">
273→                  <Terminal className="size-10 opacity-30" />
274→                  <div className="text-center">
275→                    <p className="text-sm font-medium text-foreground/80">No agent selected</p>
276→                    <p className="mt-1 text-xs">Type a prompt below to spawn a Claude agent</p>
277→                  </div>
278→                  <div className="mt-2 grid grid-cols-2 gap-3 text-[11px]">
279→                    <div className="flex items-start gap-2 rounded-lg border p-3">
280→                      <MessageSquare className="mt-0.5 size-3.5 shrink-0 text-primary" />
281→                      <div>
282→                        <p className="font-medium text-foreground/80">Chat</p>
283→                        <p className="mt-0.5">Send prompts and review tool calls in real time</p>
284→                      </div>
285→                    </div>
286→                    <div className="flex items-start gap-2 rounded-lg border p-3">
287→                      <ListTodo className="mt-0.5 size-3.5 shrink-0 text-primary" />
288→                      <div>
289→                        <p className="font-medium text-foreground/80">Tasks</p>
290→                        <p className="mt-0.5">Track work with a kanban board and delegate to agents</p>
291→                      </div>
292→                    </div>
293→                  </div>
294→                </div>
295→              ),
296→            }}
297→          />
298→        )}
299→        {!atBottom && displayItems.length > 0 && !showRaw && !loading && (
300→          <button
301→            onClick={() => virtuosoRef.current?.scrollToIndex({ index: displayItems.length - 1, behavior: "smooth" })}
302→            className="absolute bottom-3 right-3 flex items-center gap-1 rounded-full border bg-background/90 px-3 py-1.5 text-xs text-muted-foreground shadow-md backdrop-blur transition-colors hover:text-foreground"
303→          >
304→            <ArrowDown className="size-3" />
305→            Latest
306→          </button>
307→        )}
308→      </div>
309→
310→      {isArchived && messages.length > 0 ? (
311→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
312→          This session has ended
313→        </div>
314→      ) : (
315→        <div className="border-t">
316→          {/* Prompt templates — spawn mode only */}
317→          {!isActive && (
318→            <div className="flex flex-wrap gap-1.5 px-2 pt-2 md:px-4">
319→              {PROMPT_TEMPLATES.map((t) => (
320→                <button
321→                  key={t.label}
322→                  type="button"
323→                  onClick={() => { setInput(t.prompt); inputRef.current?.focus(); }}
324→                  className="rounded-full border px-2.5 py-1 text-[11px] text-muted-foreground transition-colors hover:border-foreground/30 hover:text-foreground"
325→                >
326→                  {t.label}
327→                </button>
328→              ))}
329→              <button
330→                type="button"
331→                onClick={() => setShowSystemPrompt((v) => !v)}
332→                className="ml-auto flex items-center gap-1 rounded-full border px-2.5 py-1 text-[11px] text-muted-foreground transition-colors hover:border-foreground/30 hover:text-foreground"
333→              >
334→                {showSystemPrompt ? <ChevronDown className="size-3" /> : <ChevronRight className="size-3" />}
335→                System prompt
336→              </button>
337→            </div>
338→          )}
339→
340→          {/* System prompt textarea — spawn mode only */}
341→          {!isActive && showSystemPrompt && (
342→            <div className="px-2 pt-1.5 md:px-4">
343→              <textarea
344→                value={systemPrompt}
345→                onChange={(e) => setSystemPrompt(e.target.value)}
346→                placeholder="Optional system instructions (e.g. 'You are a code reviewer. Focus on security issues.')"
347→                rows={3}
348→                className="w-full resize-none rounded-md border bg-background px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-ring"
349→              />
350→            </div>
351→          )}
352→
353→          <form
354→            onSubmit={handleSubmit}
355→            className="relative flex gap-2 px-2 py-2 md:px-4 md:py-3"
356→          >
357→            {showSlashMenu && (
358→              <SlashCommandMenu
359→                query={slashQuery}
360→                highlightedIndex={slashHighlight}
361→                onSelect={handleCommandSelect}
362→                onHighlight={setSlashHighlight}
363→              />
364→            )}
365→            <input
366→              ref={inputRef}
367→              type="text"
368→              value={input}
369→              onChange={handleInputChange}
370→              onKeyDown={handleKeyDown}
371→              placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
372→              className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
373→            />
374→            <Button type="submit" disabled={!connected || !input.trim()}>
375→              {isActive ? "Send" : "Spawn"}
376→            </Button>
377→          </form>
378→        </div>
379→      )}
380→    </div>
381→  );
382→}
383→
384→const PROMPT_TEMPLATES = [
385→  { label: "Review code", prompt: "Review the recent changes and provide feedback on code quality, bugs, and improvements." },
386→  { label: "Write tests", prompt: "Write comprehensive tests for the recent changes." },
387→  { label: "Fix bug", prompt: "" },
388→  { label: "Refactor", prompt: "Refactor the codebase for better readability and maintainability." },
389→  { label: "Explain", prompt: "" },
390→];
391→
392→/** Badge color per Claude NDJSON message type. */
393→const TYPE_COLORS: Record<string, string> = {
394→  system: "text-yellow-500",
395→  assistant: "text-blue-400",
396→  result: "text-green-500",
397→  control_request: "text-orange-400",
398→  keep_alive: "text-muted-foreground",
399→};
400→
401→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
402→  const [expanded, setExpanded] = useState(false);
403→  const subtype = (message as { subtype?: string }).subtype;
404→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
405→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
406→
407→  return (
408→    <div className="font-mono text-[11px] leading-relaxed">
409→      <button
410→        onClick={() => setExpanded((v) => !v)}
411→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
412→      >
413→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
414→        <span className={colorClass}>{typeLabel}</span>
415→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
416→      </button>
417→      {expanded && (
418→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
419→          {JSON.stringify(message, null, 2)}
420→        </pre>
421→      )}
422→    </div>
423→  );
424→}
