  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ *
 11→ * ## Key architecture notes
 12→ *
 13→ * - On browser connect, the server sends `agent_list` + `task_list` only.
 14→ * - Message histories are loaded lazily: the browser sends
 15→ *   `request_history` when selecting an agent, and the server responds
 16→ *   with `message_history` for that single agent.
 17→ * - Live messages for active agents are broadcast via `relay` in real time.
 18→ * - See `server/ws.ts` and `hooks/use-websocket.ts` for implementation.
 19→ */
 20→
 21→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 22→
 23→/**
 24→ * Sent once after the first user prompt is received. Contains session
 25→ * metadata like the model name, working directory, and available tools.
 26→ */
 27→export interface ClaudeSystemInit {
 28→  type: "system";
 29→  subtype: "init";
 30→  session_id: string;
 31→  tools: unknown[];
 32→  mcp_servers: unknown[];
 33→  model: string;
 34→  cwd: string;
 35→}
 36→
 37→/**
 38→ * An assistant turn. `message.content` is an array of content blocks
 39→ * (text, tool_use, tool_result) that may arrive incrementally — each
 40→ * NDJSON line is a complete snapshot of the message so far.
 41→ */
 42→export interface ClaudeAssistant {
 43→  type: "assistant";
 44→  message: {
 45→    id: string;
 46→    role: "assistant";
 47→    content: AssistantContentBlock[];
 48→    model: string;
 49→    stop_reason: string | null;
 50→  };
 51→  session_id: string;
 52→}
 53→
 54→/** A single content block inside an assistant message. */
 55→export type AssistantContentBlock =
 56→  | { type: "text"; text: string }
 57→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 58→  | { type: "tool_result"; tool_use_id: string; content: string };
 59→
 60→/**
 61→ * Terminal message for a session. Includes cost/duration metrics.
 62→ * `is_error` is true when `subtype` is `"error"`.
 63→ */
 64→export interface ClaudeResult {
 65→  type: "result";
 66→  subtype: "success" | "error";
 67→  result?: string;
 68→  error?: string;
 69→  session_id: string;
 70→  cost_usd: number;
 71→  total_cost_usd?: number;
 72→  duration_ms: number;
 73→  duration_api_ms: number;
 74→  is_error: boolean;
 75→  num_turns: number;
 76→}
 77→
 78→/**
 79→ * Claude is requesting permission to execute a tool. The dashboard must
 80→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 81→ *
 82→ * Wire format uses a nested `request` object with `request_id` at the
 83→ * top level for correlation (matches Companion protocol docs).
 84→ */
 85→export interface ClaudeControlRequest {
 86→  type: "control_request";
 87→  request_id: string;
 88→  request: {
 89→    subtype: "can_use_tool";
 90→    tool_name: string;
 91→    input: Record<string, unknown>;
 92→    tool_use_id?: string;
 93→    description?: string;
 94→  };
 95→  session_id?: string;
 96→}
 97→
 98→/**
 99→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
100→ * the signal that the CLI is ready to receive the first user prompt.
101→ */
102→export interface ClaudeSystemHook {
103→  type: "system";
104→  subtype: "hook_started" | "hook_response";
105→  session_id?: string;
106→}
107→
108→/** Discriminated union of all known Claude NDJSON message shapes. */
109→export type ClaudeMessage =
110→  | ClaudeSystemInit
111→  | ClaudeAssistant
112→  | ClaudeResult
113→  | ClaudeControlRequest
114→  | ClaudeSystemHook
115→  | { type: string; subtype?: string; [key: string]: unknown };
116→
117→// ── Workspaces ───────────────────────────────────────────────────────────
118→
119→/** A workspace represents a project directory. */
120→export interface Workspace {
121→  id: string;
122→  name: string;
123→  cwd: string;
124→  createdAt: number;
125→}
126→
127→/** A directory entry returned by the server-side folder browser. */
128→export interface DirectoryEntry {
129→  name: string;
130→  path: string;
131→}
132→
133→// ── Browser ↔ Server messages ─────────────────────────────────────────────
134→
135→/** Browser asks the server to spawn a new Claude CLI process. */
136→export interface BrowserSpawn {
137→  type: "spawn";
138→  prompt: string;
139→  workspaceId?: string;
140→  /** Optional model override (e.g. "claude-opus-4-20250514", "qwen3-coder"). */
141→  model?: string;
142→  /** Optional system prompt appended via --append-system-prompt. */
143→  systemPrompt?: string;
144→}
145→
146→/** Browser sends a follow-up message to an already-running Claude session. */
147→export interface BrowserSendMessage {
148→  type: "send_message";
149→  agentId: string;
150→  content: string;
151→}
152→
153→/** Browser responds to a tool approval request (allow or deny). */
154→export interface BrowserControlResponse {
155→  type: "control_response";
156→  agentId: string;
157→  request_id: string;
158→  allow: boolean;
159→}
160→
161→/** Browser asks the server to kill a running agent's tmux session + CLI. */
162→export interface BrowserKillAgent {
163→  type: "kill_agent";
164→  agentId: string;
165→}
166→
167→/** Browser asks the server to permanently delete an agent. */
168→export interface BrowserDeleteAgent {
169→  type: "delete_agent";
170→  agentId: string;
171→}
172→
173→/** Browser asks the server to rename an agent. */
174→export interface BrowserRenameAgent {
175→  type: "rename_agent";
176→  agentId: string;
177→  label: string;
178→}
179→
180→/** Browser asks the server to clear an agent's message history. */
181→export interface BrowserClearHistory {
182→  type: "clear_history";
183→  agentId: string;
184→}
185→
186→/** Browser asks the server to pin or unpin an agent. */
187→export interface BrowserPinAgent {
188→  type: "pin_agent";
189→  agentId: string;
190→  pinned: boolean;
191→}
192→
193→/** Browser asks the server to icebox or un-icebox an agent. */
194→export interface BrowserIceboxAgent {
195→  type: "icebox_agent";
196→  agentId: string;
197→  iceboxed: boolean;
198→}
199→
200→/** Browser asks the server to move an agent to a different workspace. */
201→export interface BrowserMoveAgent {
202→  type: "move_agent";
203→  agentId: string;
204→  workspaceId: string | null;
205→}
206→
207→/** Browser requests message history for a specific agent (lazy loading). */
208→export interface BrowserRequestHistory {
209→  type: "request_history";
210→  agentId: string;
211→}
212→
213→/** Browser asks the server to create a new task. */
214→export interface BrowserCreateTask {
215→  type: "create_task";
216→  title: string;
217→  description: string;
218→  priority: TaskPriority;
219→}
220→
221→/** Browser asks to update a task's fields. */
222→export interface BrowserUpdateTask {
223→  type: "update_task";
224→  taskId: string;
225→  updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>;
226→}
227→
228→/** Browser asks to delete a task. */
229→export interface BrowserDeleteTask {
230→  type: "delete_task";
231→  taskId: string;
232→}
233→
234→/** Browser asks to delegate a task to a new Claude agent. */
235→export interface BrowserDelegateTask {
236→  type: "delegate_task";
237→  taskId: string;
238→}
239→
240→/** Browser tells the server which workspace to scope to. */
241→export interface BrowserSetWorkspace {
242→  type: "set_workspace";
243→  workspaceId: string | null;
244→}
245→
246→/** Browser asks the server to create a new workspace. */
247→export interface BrowserCreateWorkspace {
248→  type: "create_workspace";
249→  name: string;
250→  cwd: string;
251→}
252→
253→/** Browser asks to rename a workspace. */
254→export interface BrowserRenameWorkspace {
255→  type: "rename_workspace";
256→  workspaceId: string;
257→  name: string;
258→}
259→
260→/** Browser asks to delete a workspace. */
261→export interface BrowserDeleteWorkspace {
262→  type: "delete_workspace";
263→  workspaceId: string;
264→}
265→
266→/** Browser asks to browse a directory on the server. */
267→export interface BrowserBrowseDirectory {
268→  type: "browse_directory";
269→  path: string;
270→}
271→
272→/** Union of all messages the browser can send to the WS server. */
273→export type BrowserMessage =
274→  | BrowserSpawn
275→  | BrowserSendMessage
276→  | BrowserControlResponse
277→  | BrowserKillAgent
278→  | BrowserDeleteAgent
279→  | BrowserRenameAgent
280→  | BrowserClearHistory
281→  | BrowserPinAgent
282→  | BrowserIceboxAgent
283→  | BrowserMoveAgent
284→  | BrowserRequestHistory
285→  | BrowserCreateTask
286→  | BrowserUpdateTask
287→  | BrowserDeleteTask
288→  | BrowserDelegateTask
289→  | BrowserSetWorkspace
290→  | BrowserCreateWorkspace
291→  | BrowserRenameWorkspace
292→  | BrowserDeleteWorkspace
293→  | BrowserBrowseDirectory;
294→
295→/** Server relays a raw Claude NDJSON message to the browser. */
296→export interface ServerRelay {
297→  type: "relay";
298→  agentId: string;
299→  message: ClaudeMessage;
300→}
301→
302→/** Server notifies the browser of an agent status change. */
303→export interface ServerStatus {
304→  type: "status";
305→  agentId: string;
306→  status: AgentStatus;
307→}
308→
309→/** Server reports an error (e.g. no active session, process crash). */
310→export interface ServerError {
311→  type: "error";
312→  agentId: string;
313→  error: string;
314→}
315→
316→/** Summary of an agent for the sidebar. */
317→export interface AgentInfo {
318→  agentId: string;
319→  status: AgentStatus;
320→  tmuxSession: string | null;
321→  label: string;
322→  createdAt: number;
323→  workspaceId: string | null;
324→  /** Model name reported by system/init, or the model requested at spawn time. */
325→  model?: string | null;
326→  /** Whether this agent is pinned to the top of the sidebar. */
327→  pinned?: boolean;
328→  /** Whether this agent is in the icebox (parked for later). */
329→  iceboxed?: boolean;
330→}
331→
332→/** Server sends the full list of agents after every state change. */
333→export interface ServerAgentList {
334→  type: "agent_list";
335→  agents: AgentInfo[];
336→}
337→
338→/** Server confirms a new agent was spawned and assigns its ID. */
339→export interface ServerSpawned {
340→  type: "spawned";
341→  agentId: string;
342→}
343→
344→/** Server sends full message history for an agent (in response to `request_history`). */
345→export interface ServerMessageHistory {
346→  type: "message_history";
347→  agentId: string;
348→  messages: ServerMessage[];
349→}
350→
351→/** CLI WebSocket disconnected (process may have crashed or exited). */
352→export interface ServerCliDisconnected {
353→  type: "cli_disconnected";
354→  agentId: string;
355→}
356→
357→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
358→export interface ServerCliConnected {
359→  type: "cli_connected";
360→  agentId: string;
361→}
362→
363→/** Server confirms message history was cleared for an agent. */
364→export interface ServerHistoryCleared {
365→  type: "history_cleared";
366→  agentId: string;
367→}
368→
369→/** Server sends the full workspace list to the browser. */
370→export interface ServerWorkspaceList {
371→  type: "workspace_list";
372→  workspaces: Workspace[];
373→}
374→
375→/** Server responds with a directory listing for the folder browser. */
376→export interface ServerDirectoryListing {
377→  type: "directory_listing";
378→  path: string;
379→  entries: DirectoryEntry[];
380→}
381→
382→/** Server sends the full task list to the browser. */
383→export interface ServerTaskList {
384→  type: "task_list";
385→  tasks: Task[];
386→}
387→
388→/** Server confirms a task was updated. */
389→export interface ServerTaskUpdated {
390→  type: "task_updated";
391→  task: Task;
392→}
393→
394→/** Server confirms a task was deleted. */
395→export interface ServerTaskDeleted {
396→  type: "task_deleted";
397→  taskId: string;
398→}
399→
400→/** Union of all messages the WS server can send to the browser. */
401→export type ServerMessage =
402→  | ServerRelay
403→  | ServerStatus
404→  | ServerError
405→  | ServerAgentList
406→  | ServerSpawned
407→  | ServerMessageHistory
408→  | ServerCliDisconnected
409→  | ServerCliConnected
410→  | ServerHistoryCleared
411→  | ServerWorkspaceList
412→  | ServerDirectoryListing
413→  | ServerTaskList
414→  | ServerTaskUpdated
415→  | ServerTaskDeleted;
416→
417→// ── UI state ──────────────────────────────────────────────────────────────
