 30→function formatRelativeTime(ts: number): string {
 31→  const diff = Date.now() - ts;
 32→  if (diff < 10_000) return "just now";
 33→  if (diff < 60_000) return `${Math.floor(diff / 1000)}s ago`;
 34→  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)}m ago`;
 35→  if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)}h ago`;
 36→  return `${Math.floor(diff / 86_400_000)}d ago`;
 37→}
 38→
 39→function formatAbsoluteTime(ts: number): string {
 40→  return new Date(ts).toLocaleString();
 41→}
 42→
 43→function RelativeTime({ timestamp }: { timestamp: number }) {
 44→  const [, setTick] = useState(0);
 45→
 46→  useEffect(() => {
 47→    const id = setInterval(() => setTick((t) => t + 1), 30_000);
 48→    return () => clearInterval(id);
 49→  }, []);
 50→
 51→  return (
 52→    <time
