/**
 * Extract the plan markdown content from a condensed group that contains
 * an ExitPlanMode tool call. The plan is written via a Write tool call
 * to a `.md` file (typically under `~/.claude/plans/`).
 */
function extractPlanContent(allToolCalls: ToolCallInfo[]): string | null {
  const hasExit = allToolCalls.some((tc) => tc.name === "ExitPlanMode");
  if (!hasExit) return null;

  // Find the Write call that wrote the plan .md file
  for (const tc of allToolCalls) {
    if (tc.name === "Write" && tc.input?.file_path && tc.input?.content) {
      const fp = String(tc.input.file_path);
      if (fp.endsWith(".md")) {
        return String(tc.input.content);
      }
    }
  }
  return null;
}

