  1→"use client";
  2→
  3→/**
  4→ * Collapsible group for consecutive tool-only assistant messages.
  5→ *
  6→ * When Claude runs multiple tools in a row without any prose text,
  7→ * {@link condenseMessages} in `lib/condense-messages.ts` groups them
  8→ * into a {@link CondensedGroup}. This component renders that group.
  9→ *
 10→ * ## Two-level expand
 11→ *
 12→ * 1. **Group level** — The top chevron toggles between the compact
 13→ *    per-tool-call summary (collapsed) and the full message bubbles
 14→ *    (expanded). This is the original behavior.
 15→ *
 16→ * 2. **Diff level** — In the collapsed view, file-modifying tool calls
 17→ *    (Edit, Write, MultiEdit) show the file basename and are clickable.
 18→ *    Clicking one toggles an inline {@link DiffViewer} for just that
 19→ *    tool call, without expanding the whole group. Multiple diffs can
 20→ *    be open at once (tracked in the `expandedDiffs` Set).
 21→ *
 22→ * Non-diff tool calls (Read, Bash, Grep, etc.) continue to show the
 23→ * truncated `resultPreview` text as before.
 24→ */
 25→
 26→import { memo, useState } from "react";
 27→import { ChevronRight, Maximize2, Minimize2 } from "lucide-react";
 28→import Markdown from "react-markdown";
 29→import remarkGfm from "remark-gfm";
 30→import type { CondensedGroup } from "@/lib/condense-messages";
 31→import type { ToolCallInfo } from "@/lib/types";
 32→import { Message } from "./message";
 33→import { DiffViewer } from "./diff-viewer";
 34→import { Tip } from "@/components/ui/tip";
 35→import { cn } from "@/lib/utils";
 36→
 37→/** Colored dot per common tool name (used in the compact summary line). */
 38→const TOOL_COLORS: Record<string, string> = {
 39→  Read: "bg-blue-400",
 40→  Write: "bg-green-400",
 41→  Edit: "bg-yellow-400",
 42→  Bash: "bg-orange-400",
 43→  Glob: "bg-purple-400",
 44→  Grep: "bg-cyan-400",
 45→  WebFetch: "bg-pink-400",
 46→  Task: "bg-indigo-400",
 47→  TodoWrite: "bg-teal-400",
 48→};
 49→
 50→/** Tool names that produce renderable diffs (same set as in diff-viewer). */
 51→const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
 52→
 53→/**
 54→ * Extract the plan markdown content from a condensed group that contains
 55→ * an ExitPlanMode tool call. The plan is written via a Write tool call
 56→ * to a `.md` file (typically under `~/.claude/plans/`).
 57→ */
 58→function extractPlanContent(allToolCalls: ToolCallInfo[]): string | null {
 59→  const hasExit = allToolCalls.some((tc) => tc.name === "ExitPlanMode");
 60→  if (!hasExit) return null;
 61→
 62→  // Find the Write call that wrote the plan .md file
 63→  for (const tc of allToolCalls) {
 64→    if (tc.name === "Write" && tc.input?.file_path && tc.input?.content) {
 65→      const fp = String(tc.input.file_path);
 66→      if (fp.endsWith(".md")) {
 67→        return String(tc.input.content);
 68→      }
 69→    }
 70→  }
 71→  return null;
 72→}
 73→
 74→export const CondensedToolGroup = memo(function CondensedToolGroup({ group, onSendMessage }: { group: CondensedGroup; onSendMessage?: (content: string) => void }) {
 75→  /** Whether the full message list is shown (group-level expand). */
 76→  const [expanded, setExpanded] = useState(false);
 77→  /** Which individual diffs are open in the collapsed view (by key). */
 78→  const [expandedDiffs, setExpandedDiffs] = useState<Set<string>>(new Set());
 79→  /** Whether the plan card is shown in full-width mode. */
 80→  const [planExpanded, setPlanExpanded] = useState(true);
 81→
 82→  // Collect all tool calls with previews for the collapsed view
 83→  const allToolCalls: ToolCallInfo[] = [];
 84→  for (const msg of group.messages) {
 85→    for (const tc of msg.toolCalls ?? []) {
 86→      allToolCalls.push(tc);
 87→    }
 88→  }
 89→
 90→  const planContent = extractPlanContent(allToolCalls);
 91→
 92→  function toggleDiff(key: string) {
 93→    setExpandedDiffs((prev) => {
 94→      const next = new Set(prev);
 95→      if (next.has(key)) next.delete(key);
 96→      else next.add(key);
 97→      return next;
 98→    });
 99→  }
100→
101→  // Plan mode: render the plan as a prominent card instead of a tool summary
102→  if (planContent) {
103→    return (
104→      <div className="py-1">
105→        <div className="flex items-center gap-2 px-3 py-1.5">
106→          <span className="text-[10px] font-medium uppercase tracking-wider text-indigo-400">Plan</span>
107→          <button
108→            onClick={() => setPlanExpanded((v) => !v)}
109→            className="flex items-center gap-1 rounded px-1.5 py-0.5 text-[10px] text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors"
110→            aria-label={planExpanded ? "Collapse plan" : "Expand plan"}
111→          >
112→            {planExpanded ? <Minimize2 className="size-3" /> : <Maximize2 className="size-3" />}
113→            {planExpanded ? "Collapse" : "Expand"}
114→          </button>
115→          <button
116→            onClick={() => setExpanded((v) => !v)}
117→            className="ml-auto flex items-center gap-1 text-[10px] text-muted-foreground hover:text-foreground transition-colors"
118→          >
119→            <ChevronRight className={cn("size-3 transition-transform", expanded && "rotate-90")} />
120→            <span className="font-mono">{group.summary}</span>
121→          </button>
122→        </div>
123→
124→        {planExpanded && (
125→          <div className="mt-1 rounded-lg border border-indigo-500/20 bg-secondary px-4 py-3 text-sm prose-msg">
126→            <Markdown remarkPlugins={[remarkGfm]}>{planContent}</Markdown>
127→          </div>
128→        )}
129→
130→        {expanded && (
131→          <div className="ml-5 mt-1 space-y-1 border-l border-muted pl-3">
132→            {group.messages.map((msg) => (
133→              <Message key={msg.id} message={msg} onSendMessage={onSendMessage} />
134→            ))}
135→          </div>
136→        )}
137→      </div>
138→    );
139→  }
140→
141→  return (
142→    <div className="py-1">
143→      <button
144→        onClick={() => setExpanded((v) => !v)}
145→        aria-expanded={expanded}
146→        className="flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-xs text-muted-foreground hover:bg-muted/50 transition-colors"
147→      >
148→        <ChevronRight
149→          className={cn(
150→            "size-3 shrink-0 transition-transform",
151→            expanded && "rotate-90"
152→          )}
153→        />
154→        <span className="font-mono">{group.summary}</span>
155→      </button>
156→
157→      {!expanded && allToolCalls.length > 0 && (
158→        <div className="ml-5 mt-0.5 space-y-0.5 pl-3">
159→          {allToolCalls.map((tc, i) => {
160→            const key = `${tc.toolUseId ?? "tc"}-${i}`;
161→            const hasDiff = tc.input && DIFF_TOOLS.has(tc.name);
162→            const diffOpen = expandedDiffs.has(key);
163→
164→            return (
165→              <div key={key}>
166→                <div
167→                  className={cn(
168→                    "flex items-center gap-1.5 text-[10px] text-muted-foreground/70 truncate",
169→                    hasDiff && "cursor-pointer hover:text-muted-foreground"
170→                  )}
171→                  onClick={hasDiff ? () => toggleDiff(key) : undefined}
172→                >
173→                  <span className={cn("inline-block size-1.5 shrink-0 rounded-full", TOOL_COLORS[tc.name] ?? "bg-muted-foreground/50")} />
174→                  <span className="font-mono shrink-0">{tc.name}</span>
175→                  {hasDiff && tc.input?.file_path ? (
176→                    <Tip text={String(tc.input.file_path)}>
177→                      <span className="truncate font-mono opacity-80">
178→                        {String(tc.input.file_path).split("/").pop()}
179→                      </span>
180→                    </Tip>
181→                  ) : tc.resultPreview ? (
182→                    <Tip text={tc.resultPreview}><span className="truncate opacity-60">{tc.resultPreview}</span></Tip>
183→                  ) : null}
184→                </div>
185→                {hasDiff && diffOpen && (
186→                  <div className="mt-1 mb-1">
187→                    <DiffViewer toolCall={tc} onComment={onSendMessage} defaultExpanded />
188→                  </div>
189→                )}
190→              </div>
191→            );
192→          })}
193→        </div>
194→      )}
195→
196→      {expanded && (
197→        <div className="ml-5 mt-1 space-y-1 border-l border-muted pl-3">
198→          {group.messages.map((msg) => (
199→            <Message key={msg.id} message={msg} onSendMessage={onSendMessage} />
200→          ))}
201→        </div>
202→      )}
203→    </div>
204→  );
205→});
